<template><AppShell title="活动中心" back><view class="pad activities-page"><text class="muted">最新活动在上方，往期内容随时回看</text><view v-for="section in sections" :key="section.key" class="section"><view class="row between"><text class="section-title">{{section.label}}</text><text class="muted tiny">{{state[section.key].total}} 个活动</text></view><StateView :loading="state[section.key].loading" :error="state[section.key].error" :count="state[section.key].items.length" :title="section.key==='current'?'暂无新活动':'暂无历史活动'" @retry="load(section.key)" /><button v-for="a in state[section.key].items" :key="a.id" class="ui-button activity-row" @click="go('content/activity',{id:a.id})"><image :src="contentImage(a.cover)" mode="aspectFill" /><view class="activity-copy"><text class="bold">{{a.title}}</text><text class="muted tiny activity-summary">{{a.summary}}</text><view class="row between"><text class="muted tiny">{{date(a.publishedAt||a.createdAt)}}</text><text class="tag" :class="{gray:a.phase==='ENDED'}">{{phases[a.phase]}}</text></view></view></button><button v-if="state[section.key].items.length<state[section.key].total" class="ui-button load-more" :disabled="state[section.key].loading" @click="load(section.key,true)">查看更多</button></view></view></AppShell></template>
<script setup>
import {reactive} from 'vue';import {onShow,onUnload} from '@dcloudio/uni-app';import AppShell from '../../components/AppShell.vue';import StateView from '../../components/StateView.vue';import {request,go,date} from '../../lib/api';import {contentImage} from '../../lib/content'
const sections=[{key:'current',label:'最新活动'},{key:'history',label:'历史活动'}],phases={UPCOMING:'即将开始',ONGOING:'进行中',ENDED:'已结束'},state=reactive(Object.fromEntries(sections.map(s=>[s.key,{items:[],total:0,page:1,loading:false,error:''}])));let generation=0
onShow(()=>{generation++;for(const s of sections)load(s.key)});onUnload(()=>generation++)
async function load(key,more=false){const row=state[key],v=generation;if(more&&row.loading)return;row.loading=true;row.error='';if(!more){row.items=[];row.page=1}try{const page=more?row.page+1:1,r=await request('/boost/content/activities','GET',{scope:key,page});if(v!==generation)return;row.items=more?[...row.items,...r.items]:r.items;row.total=r.total;row.page=page}catch(e){if(v===generation)row.error=e.message}finally{if(v===generation)row.loading=false}}
</script>
<style scoped>.activity-row{display:flex;width:100%;padding:14px 0;margin-top:10px;border-bottom:1px solid var(--line);text-align:left;gap:14px;min-height:112px}.activity-row image{width:104px;height:90px;border-radius:10px;flex-shrink:0}.activity-copy{display:flex;flex-direction:column;justify-content:space-between;gap:8px;min-width:0;flex:1}.activity-copy>.bold{font-size:16px;line-height:1.4}.activity-summary{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.activities-page{background:#fff;min-height:calc(100vh - 62px)}.section-title{font-size:20px}</style>
